/**
 * THE FAMILY
 * ----------
 * The book is written for one real child, so the hero is him and the family
 * around him is his own. Every adventure starts and ends in his actual house in
 * Satkhira -- he goes, he learns, he comes home and uses it. That loop is what
 * turns the story into practice.
 *
 * Two grandfathers do a lot of quiet work here: Dada is a zoology professor
 * (so science enters through a person the child loves and trusts, not a
 * lecture), and Nana runs a big agricultural business (so rizq, seeds, growth
 * and gratitude have somewhere concrete to live).
 *
 * ON THE NAME -- important:
 * The hero is Mahdi, and the awaited al-Mahdi inspires him. He is NOT him, and
 * the book never hints that he is. Claiming Mahdi-hood is a serious matter and
 * history is full of false claimants. What the book says is: your name means
 * "rightly guided", so *earn* it -- be just, learn deeply, be brave, serve.
 * "Be like him" is also simply the better story: it hands the child a job
 * instead of a title.
 */
