/**
 * THE STORY BIBLE
 * ---------------
 * One arc across all 24 weeks, so every class pulls in the same direction.
 *
 * The child is not a passenger -- from Island 3 they are made **সেনাপতি**
 * (commander). But the army they command is knowledge, and the weapons are
 * memorised Quran, good character, and hard study. The victory the story ends
 * on is the classical one from the hadith: Isa (AS) descends, the great deceiver
 * is undone, and the earth fills with justice and peace.
 *
 * A NOTE ON SCIENCE (deliberate editorial rule):
 * The wonder threads below are written as OPEN QUESTIONS and awe -- "বিজ্ঞানীরা
 * আজও জানেন না...", "ভাবো তো!" -- never as "the Quran proved this". Overclaimed
 * science-miracle arguments tend to collapse when the child grows up and
 * actually studies the subject, and a collapsed argument damages faith instead
 * of building it. Humility is both more honest and more durable.
 */
