      'আর শপথটা এত জীবন্ত যে তুমি দৃশ্যটা শুনতে পাও: খুরের শব্দ, পাথরে ঠোকা লেগে ফুলকি, ভোরের কুয়াশা ফুঁড়ে ঝাঁপিয়ে পড়া, ধুলোর মেঘ।',
