    why: 'সূরাটা ওজনের ধারণাটা বদলে দেয়। দুনিয়ায় ভারী মানে বড়, দামি, চকচকে। সেদিন ভারী মানে **সুন্দর চরিত্র** আর ছোট ছোট ভালো কাজ।',
