    why: 'সূরাটা প্রতিযোগিতাকে নিষেধ করে না — **ভুলে যাওয়াকে** নিষেধ করে। শব্দটা **أَلْهَىٰ** (ভুলিয়ে রাখা)। জিনিস দোষের নয়; জিনিস যখন আসল কাজ ভুলিয়ে দেয়, তখনই দোষ।',
