    why: 'সূরাটা প্রমাণ করে আল্লাহর হিসাব মানুষের হিসাবের মতো নয়। **তুমি ছোট, তোমার সময় কম — কিন্তু তোমার রব বড়।** একটা রাত একটা জীবনকে ছাড়িয়ে যেতে পারে।',
