      'তারপর এল সেই লাইন, যেটা চৌদ্দশো বছর ধরে কোটি মানুষ কঠিন সময়ে আঁকড়ে ধরেছে — **إِنَّ مَعَ ٱلْعُسْرِ يُسْرًا**।',
