    why: 'সূরাটা শেষ হয় বসে থাকার নির্দেশ দিয়ে নয় — **উঠে দাঁড়ানোর** নির্দেশ দিয়ে: *যখনই অবসর পাও, পরিশ্রম করো*। আল্লাহ কাঁদতে বারণ করেননি; শুধু বলেছেন কান্না শেষে **কাজে লাগো**।',
