      '"তাই আল্লাহ পাঠালেন সূরা মাসাদ — **تَبَّتْ يَدَآ أَبِى لَهَبٍ** *(তাব্বাত ইয়াদা আবী লাহাব — ধ্বংস হোক আবু লাহাবের দুই হাত)*।"',
