    tip: { title: 'হাত থেকে গলা', body: 'সূরাটা ছবির মতো: **دَا** (দুই হাত) → **مَال** (সম্পদ) → **نَار** (আগুন) → **حَطَب** (লাকড়ি) → **جِيد** (গলা)। উপর থেকে নিচে — হাত, সম্পদ, আগুন, লাকড়ি, গলার দড়ি। ছবিটা মনে আঁকো।' },
