      'সকালে মাহদী নানাকে জিজ্ঞেস করল, "নানা, কালু বৃষ্টিতে ভেতরে আসে না কেন? আমি তো ডেকেছিলাম।"',
      '"আসবে না," নানা চা ঢালতে ঢালতে বললেন। "সাত বছর ধরে ওই গেট ওর। কেউ ওকে বলেনি বসে থাকতে, কেউ ওকে বেতনও দেয় না।"',
