      '"হ্যাঁ। কিন্তু পরেরটা আরও গভীর।" হুদহুদ থামল। "**وَحُصِّلَ مَا فِى ٱلصُّدُورِ** *(ওয়া হুস্সিলা মা ফিস সুদূর — আর বুকের ভেতরে যা আছে, তা বের করে আনা হবে)*।"',
