      '"সেদিন শুধু তোমার **কাজ** নয়," হুদহুদ বলল, "তোমার **নিয়ত**ও ঝেড়ে বের করা হবে। কে কোন কাজটা **কেন** করেছিল, সেটাও।"',
      'মাহদী অনেকক্ষণ চুপ করে রইল।',
