    tip: { title: 'নিশ্চিত হওয়ার তিন সিঁড়ি', body: '**علم اليقين** (জেনে) → **عين اليقين** (দেখে) → **حق اليقين** (ছুঁয়ে)। তিনটে ধাপ মনে রাখো দাদার চুলা দিয়ে: শুনেছি → দেখেছি → হাত দিয়েছি। বুদ্ধিমান মানুষ **প্রথম ধাপেই** থেমে যায়।' },
