    tip: { title: 'ভয় পেয়ো না — প্রস্তুত হও', body: 'এই আয়াতগুলো তোমাকে ভয় দেখাতে আসেনি। মনে রেখো তিনটে কথা: **এক** — নবীজি (সা.) আগেই সব বলে দিয়েছেন, তাই আমরা প্রস্তুত। **দুই** — সে কোনোদিন মক্কা আর মদিনায় ঢুকতে পারবে না। **তিন** — সূরা কাহাফের প্রথম দশ আয়াত মুখস্থ থাকলে তুমি নিরাপদ। <sub>📚 সহীহ মুসলিম ৮০৯</sub> **আর সেই সূরাটা তুমি এই বইয়ের শেষেই শিখবে।**' },
