      '**كَلَّا لَئِن لَّمْ يَنتَهِ لَنَسْفَعًۢا بِٱلنَّاصِيَةِ** *(কাল্লা লাইল লাম ইয়ানতাহি লানাসফাআম বিন নাসিয়াহ — কখনো নয়! সে যদি বিরত না হয়, আমরা অবশ্যই তাকে হেঁচড়ে নেব সামনের চুলের গুচ্ছ ধরে)*',
