      '"শোনো সেনাপতি। দাজ্জালের গোটা কাজটাই একটা মিথ্যা — সে বলবে *আমি সবচেয়ে বড়*। এখন বলো, পৃথিবীর কোন কাজটা এই মিথ্যার একদম উল্টো?"',
