      'নামাজ শেষে অদ্ভুত একটা অনুভূতি হলো — যেন ঘরটা আগের চেয়ে **বড়** লাগছে।',
      'সন্ধ্যায় সবাই ফিরল। কেউ জিজ্ঞেস করল না নামাজ পড়েছে কি না।',
      'মাহদীও বলল না।',
