      '"তাহলে স্বীকার করেও লাভ হলো না?"',
      '"এখানেই আজকের সবচেয়ে বড় পাঠ।" হুদহুদ থামল। "স্বীকার করার একটা **সময়** আছে।"',
      '"সময় পার হয়ে গেলে?"',
