      '"আর আরবিতে সৈনিকের শিরস্ত্রাণকেও বলে **مِغْفَر** — যা মাথা ঢেকে রক্ষা করে।"',
      'হুদহুদ ডানা নামিয়ে নরম গলায় বলল —',
