    tip: { title: 'ভয় থেকে আশায়, এক আয়াতে', body: 'সূরা মূলকের এই অংশটা এক ঝটকায় ঘুরে যায়: **স্বীকারোক্তি ও ধ্বংস (আয়াত ১১)** → **ক্ষমা ও মহাপুরস্কার (আয়াত ১২)**। মাঝখানে কিছু নেই — **একটা আয়াতের ব্যবধানে দুইটা জগৎ।** পার্থক্য গড়ে দিয়েছে একটাই শব্দ: **بِٱلْغَيْبِ** — *না-দেখা অবস্থায়*। দুইটা আয়াত সবসময় **একসাথে** পড়ো। 🤍' },
