      'হুদহুদ অনেকক্ষণ চুপ করে রইল।',
      '"মাহদী," সে শেষে বলল, "তোমার নানা সারাজীবন চাষ করেছেন। তোমার আব্বু কৃষিবিজ্ঞানী। তোমার আম্মু মাটিতে সেন্সর বসান।"',
