      '"এখন ভাবো — আল্লাহ কুরআনে পুনরুত্থান বোঝানোর জন্য সবচেয়ে বেশি কোন উপমাটা ব্যবহার করেছেন?"',
      'মাহদী মুখ তুলল, আর তার চোখ ভিজে এল।',
