    tip: { title: 'এক আয়াতে চার ধাপ', body: 'আয়াতটা একটা সিঁড়ি: **ذَلُولًا** (মাটি বশ হলো) → **فَٱمْشُوا۟** (হাঁটো) → **وَكُلُوا۟** (খাও) → **وَإِلَيْهِ ٱلنُّشُورُ** (তাঁর কাছেই ফিরে ওঠা)। **দুনিয়ার তিন ধাপ, তারপর চতুর্থ ধাপে আখেরাত।** এই ক্রমটা মাথায় রাখলে আয়াতের অর্ধেক মুখস্থ হয়ে গেছে। 🪜' },
