      'মাহদী গুনল। **এক মিনিট। দুই মিনিট।** চিলটা একবারও ডানা নাড়ল না — শুধু ধীরে ধীরে উঁচুতে উঠতে লাগল।',
      '"এটা কীভাবে হয় দাদা?"',
      '"গরম বাতাস উপরে ওঠে, দাদুভাই। পাখিটা সেই উঠন্ত বাতাসের উপর **ভেসে** থাকে। এর নাম থার্মাল।"',
      '"তার মানে বিজ্ঞানে ব্যাখ্যা আছে?"',
