      '"একই শব্দ, সেনাপতি।" হুদহুদ বলল। "**صَفّ** মানে সারিবদ্ধ হওয়া, মেলে ধরা। ফেরেশতারা সারি বাঁধেন, তুমি নামাজে সফে দাঁড়াও, আর পাখি আকাশে ডানা মেলে ধরে — **একই শব্দ, তিন জায়গায়।**"',
