    tip: { title: 'ত্রিশ আয়াত শেষ — এবার ধরে রাখো', body: 'আজ থেকে **রোজ রাতে পুরো সূরা মূলক** পড়ো — দাদির নিয়ম। প্রথম কয়েক দিন কষ্ট হবে, তারপর অভ্যাস হয়ে যাবে। আর মনে রেখো ক্লাস ৮৮-এর নিয়ম: **নতুন যত, পুরনো তার দ্বিগুণ।** সূরাটা এখন তোমার — কিন্তু **যে সূরা এক মাস ছুঁয়ে দেখোনি, সেটা আর তোমার নেই।** 🌙' },
    game: { title: '🎮 খেলা: এক গ্লাস পানির হিসাব', body: 'আজ একটা গ্লাসে পানি নাও। খাওয়ার আগে **এক মিনিট** ধরে রাখো, আর ভাবো — এই পানিটা কোথা থেকে এল? বৃষ্টি → মাটি → নলকূপ → বালতি → গ্লাস। এবার গোনো তোমার বাড়িতে আজ কতবার কল খোলা হয়েছে। **তারপর আয়াতটা পড়ো, আর বলো আলহামদুলিল্লাহ।** 💧' },
