      'মাহদী দেখল — চারপাশে অন্ধকার নেমে এসেছে। কিন্তু অদ্ভুত অন্ধকার। **অনেক রকম** অন্ধকার — কোথাও কালো, কোথাও ধোঁয়াটে, কোথাও ঘোলা।',
