      '"আর এখানে **أَوْلِيَاء** বহুবচন — কারণ **মিথ্যা অভিভাবক অনেক**। কিন্তু আগের লাইনে **وَلِىّ** একবচন — কারণ **আসল অভিভাবক একজন।**"',
      'মাহদী অনেকক্ষণ চুপ করে রইল।',
      '"হুদহুদ, একটা প্রশ্ন করি?"',
