    tip: { title: 'বহুবচন আর একবচনের খেলা', body: 'এই এক আয়াতে চারবার শব্দ-সংখ্যার খেলা: **وَلِىّ** (একবচন — আসল অভিভাবক একজন) ⟷ **أَوْلِيَاء** (বহুবচন — মিথ্যা অভিভাবক অনেক) · **ٱلنُّور** (একবচন — আলো একটাই) ⟷ **ٱلظُّلُمَات** (বহুবচন — অন্ধকার হাজার রকম)। **এই একটা নিয়ম মনে রাখলে কুরআনের বহু জায়গা খুলে যাবে।** 💡' },
