      'ভদ্রলোক বললেন, "স্যার, মনে আছে? আমি ফেল করতে করতে বেঁচে গিয়েছিলাম। আপনি একদিন ক্লাসের পরে আমাকে ডেকে বলেছিলেন — *তুই বোকা না, তুই শুধু ভয় পাস।*"',
      'দাদা হেসে ফেললেন। "মনে নেই তো!"',
