    tip: { title: 'ছয় দোয়ার সিঁড়ি', body: 'শেষ অংশটা ছয় ধাপের সিঁড়ি: **ভুলের জন্য পাকড়াও নয় → ভারী বোঝা নয় → সাধ্যের বাইরে নয় → মাফ → ক্ষমা → দয়া**। প্রথম তিনটে *"দিয়ো না"*, শেষ তিনটে *"দাও"*। আর তিনবার **رَبَّنَا** — দরজায় তিনবার টোকা। **এই কাঠামোটা ধরলে কুরআনের অন্যতম বড় আয়াত সহজ হয়ে যাবে।** 🪜' },
