      'তিনি ইট তুলতে তুলতে বললেন, "আমি দেয়াল দেখে বিচার করি না। **আমি দড়ি দেখে বিচার করি।** কারণ দড়িটা কখনো বদলায় না।"',
      'মাহদী অনেকক্ষণ সুতোটার দিকে তাকিয়ে রইল।',
