      '"**عِوَج** *(ইওয়াজ)*," হুদহুদ বলল। "মানে **বাঁক, ট্যারা, এঁকেবেঁকে যাওয়া**।"',
      'আর পরের আয়াতের প্রথম শব্দ — **قَيِّمًا**।',
