      '"বলো।"',
      '"উনি বললেন — দেয়াল ধীরে ধীরে বাঁকা হয়ে যায়, চোখে ধরা পড়ে না। তাই উনি **দেয়াল দেখে বিচার করেন না, দড়ি দেখে করেন।** কারণ দড়িটা কখনো বদলায় না।"',
      'হুদহুদ অনেকক্ষণ কিছু বলল না।',
