      '"**وَلَمْ يَجْعَل لَّهُۥ عِوَجَا · قَيِّمًا**," সে বলল। "*এতে কোনো বাঁক নেই। এটা সোজা।*"',
      '"তোমার রাজমিস্ত্রি চাচা আজ তোমাকে বলে দিয়েছেন এই কিতাবটা কী, মাহদী।"',
