    tip: { title: 'বাঁক নেই — তাই সোজা', body: 'দুইটা শব্দ পাশাপাশি রাখো: **عِوَج** (বাঁক) ⟷ **قَيِّم** (সোজা)। আয়াতটা প্রথমে বলল **কী নেই**, তারপর বলল **কী আছে**। এটা কুরআনের প্রিয় ধরন — *না, তারপর হ্যাঁ*। মনে আছে কালিমা? **لَا** দিয়ে মুছে ফেলা, **إِلَّا** দিয়ে প্রতিষ্ঠা। **একই কৌশল।** ⚖️' },
