    tip: { title: 'সবচেয়ে বিপজ্জনক অবস্থা', body: 'আয়াতটা তিন ধাপে নামে: **دَلَّ سَعْيُهُمْ** (দৌড় হারিয়ে গেছে) → **يَحْسَبُونَ** (তবু তারা মনে করে) → **يُحْسِنُونَ صُنْعًا** (তারা ভালোই করছে)। **হারিয়ে যাওয়া + না জানা = সবচেয়ে বড় ক্ষতি।** তাই কুরআনের সাথে নিজেকে মেলানো বন্ধ করা যাবে না — **একদিনের জন্যও না।** ⚠️' },
